@import '../../styles/table.css';
@import '../../styles/control-elevation.css';

:host {
  display: block;
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
}

import {
  Component,
  Event,
  EventEmitter,
  h,
  Host,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import {
  deriveTableSelectionState,
  formatTableResultSummary,
  nextTableGroupOrder,
  nextTableSortState,
  tableColumnSize,
  tableModelIssues,
  tableRows,
  tableRowSelectionLabel,
  toggleAllLoadedTableRows,
  toggleTableGroupCollapsed,
  toggleTableGroupSelection,
  nextTableGroupsCollapsed,
  toggleTableRowSelection,
} from './table-model';
import {
  resolveTableCellPresentation,
  type TableCellPresentation,
} from './table-cell-model';
import {
  createTableRenderModel,
  type TableRenderModel,
} from './table-render-model';
import { TableLayoutController } from './table-layout-controller';
import { TableLoadController } from './table-load-controller';
import type {
  TableCaptionVisibility,
  TableCellActionDetail,
  TableColumn,
  TableGroup,
  TableGroupCollapseChangeDetail,
  TableGroupingChangeDetail,
  TableGroupingState,
  TableLoadMoreDetail,
  TableLoadMoreMode,
  TableRow,
  TableRowActivateDetail,
  TableSelectionChangeDetail,
  TableSelectionMode,
  TableSortChangeDetail,
  TableSortState,
} from './table-types';

@Component({
  tag: 'ds-table',
  styleUrls: [
    '../../utils/interaction-fill.css',
    'Table.css',
  ],
  scoped: true,
})
export class Table {
  /** Stable column definitions. Assign through JavaScript. */
  @Prop() columns: TableColumn[] = [];
  /** Ungrouped row data. Ignored while grouping is active. Assign through JavaScript. */
  @Prop() rows: TableRow[] = [];
  /** One level of application-owned grouped data. Assign through JavaScript. */
  @Prop() groups: TableGroup[] = [];
  /** Controlled grouping column and group-order direction. */
  @Prop() grouping: TableGroupingState | null = null;
  /** Controlled member-row sort state. */
  @Prop() sort: TableSortState | null = null;
  /** Controlled collapsed group identities. Groups not listed remain expanded. */
  @Prop() collapsedGroupIds: string[] = [];

  /** Required accessible table name, retained as a native caption. */
  @Prop() caption!: string;
  /** Shows a matching presentational title bar above the native table frame. */
  @Prop() captionVisibility: TableCaptionVisibility = 'hidden';
  /**
   * Optional result summary footer. When both `displayedCount` and `totalCount`
   * are finite numbers, the table shows “Displaying {displayed} of {total}”.
   */
  @Prop() displayedCount: number | undefined;
  @Prop() totalCount: number | undefined;
  /** Supports {displayed} and {total} placeholders. */
  @Prop() resultSummaryLabel: string = 'Displaying {displayed} of {total}';
  @Prop() stickyHeader: boolean = false;
  /** Maximum scroll-region height. Numbers resolve to CSS pixels. */
  @Prop() maxHeight: string | number | undefined;
  /** Optional explicit label for the horizontal/vertical scroll region. */
  @Prop() scrollLabel: string | undefined;

  @Prop() selectionMode: TableSelectionMode = 'none';
  /** Controlled selected row identities. IDs outside the loaded rows are preserved. */
  @Prop() selectedRowIds: string[] = [];

  /** Initial loading state. Existing rows stay visible; incremental loading uses loadingMore. */
  @Prop() loading: boolean = false;
  @Prop() skeletonRows: number = 5;
  @Prop() emptyHeading: string = 'No results';
  @Prop() emptyBody: string = 'No data is available.';
  /** Initial error state. Existing rows stay visible; incremental failures use loadMoreError. */
  @Prop() error: boolean = false;
  @Prop() errorHeading: string = 'Unable to load data';
  @Prop() errorBody: string = 'The data could not be loaded.';
  @Prop() emptyCellLabel: string = 'Not available';

  /** Enable application-owned incremental loading without pagination. */
  @Prop() lazyLoading: boolean = false;
  @Prop() loadMoreMode: TableLoadMoreMode = 'auto';
  @Prop() hasMore: boolean = false;
  @Prop() loadingMore: boolean = false;
  @Prop() loadMoreError: string | undefined;
  /** Reset key for a new query/group/sort dataset. */
  @Prop() loadIdentity: string | number = 'default';
  /** IntersectionObserver root margin in CSS pixels. */
  @Prop() loadMoreThreshold: number = 0;
  @Prop() loadMoreLabel: string = 'Load more';
  @Prop() retryLabel: string = 'Retry';
  @Prop() loadingMoreLabel: string = 'Loading more results';
  @Prop() endOfResultsLabel: string = 'All results loaded';
  /** Supports {count} and {total} placeholders. */
  @Prop() rowsLoadedLabel: string = '{count} more rows loaded. {total} rows loaded.';

  @Event() dsSortChange!: EventEmitter<TableSortChangeDetail>;
  @Event() dsGroupingChange!: EventEmitter<TableGroupingChangeDetail>;
  @Event() dsGroupCollapseChange!: EventEmitter<TableGroupCollapseChangeDetail>;
  @Event() dsSelectionChange!: EventEmitter<TableSelectionChangeDetail>;
  @Event() dsLoadMore!: EventEmitter<TableLoadMoreDetail>;
  @Event() dsCellAction!: EventEmitter<TableCellActionDetail>;
  @Event() dsRowActivate!: EventEmitter<TableRowActivateDetail>;

  @State() private overflowStart = false;
  @State() private overflowEnd = false;
  @State() private scrollable = false;
  @State() private announcement = '';

  private viewportEl: HTMLElement | null = null;
  private frameEl: HTMLElement | null = null;
  private interactiveHeadEl: HTMLTableSectionElement | null = null;
  private collapseAllOverlayEl: HTMLElement | null = null;
  private stickyHeaderTableEl: HTMLTableElement | null = null;
  private tableEl: HTMLTableElement | null = null;
  private sentinelEl: HTMLElement | null = null;
  private previousModelWarning = '';
  private hasLoaded = false;
  private renderedModel: TableRenderModel | null = null;
  private readonly layoutController = new TableLayoutController({
    elements: () => ({
      viewport: this.viewportEl,
      table: this.tableEl,
      stickyHeaderTable: this.stickyHeaderTableEl,
      collapseAllOverlay: this.collapseAllOverlayEl,
      frame: this.frameEl,
      interactiveHead: this.interactiveHeadEl,
    }),
    mode: () => ({
      documentStickyHeader: this.documentStickyHeader,
      floatingCollapseAll: this.renderedModel?.collapseAllHost?.mode === 'floating',
    }),
    overflowChanged: state => {
      if (state.start !== this.overflowStart) this.overflowStart = state.start;
      if (state.end !== this.overflowEnd) this.overflowEnd = state.end;
      if (state.scrollable !== this.scrollable) this.scrollable = state.scrollable;
    },
  });
  private readonly loadController = new TableLoadController({
    state: () => ({
      lazyLoading: this.lazyLoading,
      loadMoreMode: this.loadMoreMode,
      hasMore: this.hasMore,
      loadingMore: this.loadingMore,
      loadMoreError: this.loadMoreError,
      loadIdentity: this.loadIdentity,
      loadMoreThreshold: this.loadMoreThreshold,
      containedScroll: this.resolvedMaxHeight !== undefined,
      loadingMoreLabel: this.loadingMoreLabel,
      endOfResultsLabel: this.endOfResultsLabel,
      rowsLoadedLabel: this.rowsLoadedLabel,
      loadedRowCount: this.currentLoadedRowCount(),
      viewport: this.viewportEl,
      sentinel: this.sentinelEl,
    }),
    announce: message => {
      this.announcement = message;
    },
    request: detail => {
      this.dsLoadMore.emit(detail);
    },
  });

  componentWillLoad(): void {
    this.loadController.initialize();
    this.warnModelIssues();
  }

  componentDidLoad(): void {
    this.hasLoaded = true;
    this.layoutController.connect();
    this.loadController.connect();
  }

  componentDidRender(): void {
    this.layoutController.refresh();
    this.loadController.refresh();
  }

  connectedCallback(): void {
    if (!this.hasLoaded) return;
    this.layoutController.connect();
    this.loadController.connect();
  }

  disconnectedCallback(): void {
    this.layoutController.disconnect();
    this.loadController.disconnect();
  }

  @Watch('columns')
  @Watch('grouping')
  handleStructureChange(): void {
    this.warnModelIssues();
    this.loadController.structureChanged();
  }

  @Watch('rows')
  @Watch('groups')
  handleDataChange(): void {
    this.loadController.dataChanged();
    this.warnModelIssues();
  }

  @Watch('loadIdentity')
  handleLoadIdentityChange(): void {
    this.loadController.identityChanged();
  }

  @Watch('lazyLoading')
  @Watch('loadMoreMode')
  @Watch('loadMoreThreshold')
  handleLazyConfigurationChange(): void {
    this.loadController.configurationChanged();
  }

  @Watch('loadingMore')
  handleLoadingMoreChange(loading: boolean): void {
    this.loadController.loadingChanged(loading);
  }

  @Watch('loadMoreError')
  handleLoadMoreErrorChange(error: string | undefined): void {
    this.loadController.errorChanged(error);
  }

  @Watch('hasMore')
  handleHasMoreChange(hasMore: boolean, hadMore: boolean): void {
    this.loadController.hasMoreChanged(hasMore, hadMore);
  }

  private get grouped(): boolean {
    return this.grouping !== null;
  }

  private get selectable(): boolean {
    return this.selectionMode === 'multiple';
  }

  private get documentStickyHeader(): boolean {
    return this.stickyHeader && this.resolvedMaxHeight === undefined;
  }

  private currentLoadedRows(): TableRow[] {
    return tableRows(this.rows, this.groups, this.grouped);
  }

  private currentLoadedRowCount(): number {
    return this.grouped
      ? this.groups.reduce((count, group) => count + group.rows.length, 0)
      : this.rows.length;
  }

  private createRenderModel(): TableRenderModel {
    return createTableRenderModel({
      columns: this.columns,
      rows: this.rows,
      groups: this.groups,
      grouped: this.grouped,
      selectionMode: this.selectionMode,
      selectedRowIds: this.selectedRowIds,
      collapsedGroupIds: this.collapsedGroupIds,
    });
  }

  private get resolvedMaxHeight(): string | undefined {
    if (this.maxHeight == null || this.maxHeight === '') return undefined;
    return typeof this.maxHeight === 'number' ? `${Math.max(0, this.maxHeight)}px` : this.maxHeight;
  }

  private warnModelIssues(): void {
    const issues = tableModelIssues(this.columns, this.rows, this.groups, this.grouped);
    if (!this.caption?.trim()) issues.unshift('A non-empty caption is required.');
    if (this.grouping && !this.columns.some(column => column.id === this.grouping!.columnId)) {
      issues.push(`Grouping references unknown column id: ${this.grouping.columnId}`);
    }
    if (
      this.sort &&
      !this.columns.some(column =>
        column.id === this.sort!.columnId ||
        column.headerSegments?.some(segment => segment.sortKey === this.sort!.columnId),
      )
    ) {
      issues.push(`Sorting references unknown column id: ${this.sort.columnId}`);
    }
    const stickyStart = this.columns.filter(column => column.sticky === 'start');
    const stickyEnd = this.columns.filter(column => column.sticky === 'end');
    if (stickyStart.length > 1 || (this.selectable && stickyStart.length > 0)) {
      issues.push('Only one sticky start column is supported, and row selection already owns that lane.');
    }
    if (stickyEnd.length > 1) issues.push('Only one sticky end column is supported.');
    for (const column of [...stickyStart, ...stickyEnd]) {
      if (!tableColumnSize(column)) issues.push(`Sticky column ${column.id} requires an explicit size.`);
    }
    const message = issues.join(' ');
    if (!message || message === this.previousModelWarning) return;
    this.previousModelWarning = message;
    console.warn(`[ds-table] ${message}`);
  }

  private emitSort(column: TableColumn, sortKey = column.id): void {
    if (this.grouping?.columnId === column.id && sortKey === column.id) {
      this.dsGroupingChange.emit({ grouping: nextTableGroupOrder(this.grouping) });
      return;
    }
    if (!column.sortable) return;
    this.dsSortChange.emit({ sort: nextTableSortState(this.sort, sortKey) });
  }

  private sortButtonLabel(column: TableColumn, sortKey = column.id, label = column.header): string {
    if (this.grouping?.columnId === column.id && sortKey === column.id) {
      const next = this.grouping.direction === 'asc' ? 'descending' : 'ascending';
      return `Sort ${column.header} groups ${next}. Currently grouped ${this.grouping.direction === 'asc' ? 'ascending' : 'descending'}.`;
    }

    if (this.sort?.columnId !== sortKey) return `Sort ${label} ascending`;
    if (this.sort.direction === 'asc') return `Sort ${label} descending. Currently ascending.`;
    return `Sort ${label} ascending. Currently descending.`;
  }

  private emitRowSelection(row: TableRow): void {
    const next = toggleTableRowSelection(this.selectedRowIds, row);
    const selected = next.includes(row.id);
    this.dsSelectionChange.emit({
      selectedRowIds: next,
      scope: 'row',
      changedRowId: row.id,
      selected,
    });
  }

  private emitAllSelection(): void {
    const loadedRows = this.currentLoadedRows();
    const selection = deriveTableSelectionState(loadedRows, this.selectedRowIds);
    this.dsSelectionChange.emit({
      selectedRowIds: toggleAllLoadedTableRows(this.selectedRowIds, loadedRows),
      scope: 'all-loaded',
      selected: !selection.allSelected,
    });
  }

  private emitGroupSelection(group: TableGroup): void {
    const state = deriveTableSelectionState(group.rows, this.selectedRowIds);
    this.dsSelectionChange.emit({
      selectedRowIds: toggleTableGroupSelection(this.selectedRowIds, group.rows),
      scope: 'group',
      groupId: group.id,
      selected: !state.allSelected,
    });
  }

  private rowEventOwnsActivation(event: Event): boolean {
    const currentTarget = event.currentTarget;
    return !event.composedPath().some(target => {
      if (!(target instanceof HTMLElement) || target === currentTarget) return false;
      return target.matches(
        'button, a, input, select, textarea, [role="button"], [role="checkbox"], ds-button-unfilled',
      );
    });
  }

  private emitRowActivation(row: TableRow, event: Event): void {
    if (!row.interactive || row.disabled || !this.rowEventOwnsActivation(event)) return;
    this.dsRowActivate.emit({ rowId: row.id });
  }

  private handleRowKeydown(row: TableRow, event: KeyboardEvent): void {
    if (event.target !== event.currentTarget || (event.key !== 'Enter' && event.key !== ' ')) return;
    event.preventDefault();
    this.emitRowActivation(row, event);
  }

  private renderSelectionControl(
    label: string,
    checked: boolean,
    indeterminate: boolean,
    disabled: boolean,
    onActivate: () => void,
  ) {
    return (
      <button
        class="ds-table__selection-control ds-interaction-fill__content"
        type="button"
        role="checkbox"
        aria-label={label}
        aria-checked={indeterminate ? 'mixed' : String(checked)}
        disabled={disabled}
        onClick={onActivate}
      >
        <ds-checkbox
          label=""
          size="md"
          checked={checked}
          indeterminate={indeterminate}
          presentation={true}
        />
      </button>
    );
  }

  private renderStickyEdge(sticky: TableColumn['sticky']) {
    if (!sticky) return null;
    return (
      <span
        class={`ds-table__sticky-edge ds-table__sticky-edge--${sticky}`}
        aria-hidden="true"
      />
    );
  }

  private renderCollapseAllButton() {
    return (
      <ds-button-unfilled
        class="ds-table__collapse-all"
        variant="icon"
        icon="ChevronDownUp"
        size="xs"
        style={{ width: 'var(--dimension-size-300)' }}
        aria-label="Collapse all groups"
        hasBorder={false}
        activeFill={false}
        pressScale={false}
        onDsClick={event => {
          event.stopPropagation();
          this.emitAllGroupsCollapse();
        }}
      />
    );
  }

  private renderFloatingCollapseAll(model: TableRenderModel) {
    if (model.collapseAllHost?.mode !== 'floating') return null;
    return (
      <span
        class="ds-table__collapse-all-overlay"
        ref={element => {
          this.collapseAllOverlayEl = element ?? null;
        }}
      >
        <span class="ds-table__collapse-all-surface ds-control-elevation ds-control-elevation--md">
          {this.renderCollapseAllButton()}
        </span>
      </span>
    );
  }

  private renderColumnHeader(
    column: TableColumn,
    model: TableRenderModel,
    interactive = true,
    presentational = false,
  ) {
    const groupedColumn = this.grouping?.columnId === column.id;
    const headerSegments = column.headerSegments?.length
      ? column.headerSegments
      : [{ label: column.header, sortKey: column.id }];
    const activeMemberSegment = !groupedColumn
      ? headerSegments.find(segment => segment.sortKey === this.sort?.columnId)
      : undefined;
    const activeMemberSort = !!activeMemberSegment;
    const activeSort = groupedColumn || activeMemberSort;
    const align = column.align ?? 'start';
    const direction = groupedColumn
      ? this.grouping!.direction
      : activeMemberSort
        ? this.sort!.direction
        : undefined;
    const memberAriaSort = activeMemberSort
      ? (this.sort!.direction === 'asc' ? 'ascending' : 'descending')
      : undefined;

    const labelControl = (
      <span class="ds-table__header-labels">
        {headerSegments.map((segment, index) => {
          const segmentActive = groupedColumn
            ? headerSegments.length === 1
            : activeMemberSegment?.sortKey === segment.sortKey;
          const segmentInteractive = interactive && (
            !!column.sortable || (groupedColumn && segment.sortKey === column.id)
          );
          const label = (
            <ds-text
              class="ds-table__header-label-box ds-control-label-box"
              as="span"
              variant="text-caption"
              emphasis={segmentActive}
              color="inherit"
              lineTruncation={1}
            >
              {segment.label}
            </ds-text>
          );
          const control = segmentInteractive ? (
            <button
              class="ds-table__header-label ds-table__header-label--interactive"
              type="button"
              aria-label={this.sortButtonLabel(column, segment.sortKey, segment.label)}
              data-sort-control="label"
              data-sort-key={segment.sortKey}
              data-sort-active={segmentActive ? 'true' : undefined}
              onClick={() => this.emitSort(column, segment.sortKey)}
            >
              {label}
            </button>
          ) : (
            <span class="ds-table__header-label ds-table__header-static">{label}</span>
          );

          return (
            <span class="ds-table__header-segment" key={segment.sortKey}>
              {control}
              {index < headerSegments.length - 1 && (
                <ds-text
                  class="ds-table__header-separator"
                  as="span"
                  variant="text-caption"
                  color="tertiary"
                  aria-hidden="true"
                >
                  {segment.separator ?? '/'}
                </ds-text>
              )}
            </span>
          );
        })}
      </span>
    );
    const sortControl = interactive ? (
      <span class="ds-table__sort-slot">
        {activeSort && (
          <ds-button-unfilled
            class="ds-table__sort-direction"
            variant="icon"
            icon={direction === 'asc' ? 'ArrowUp' : 'ArrowDown'}
            size="xs"
            aria-label={this.sortButtonLabel(
              column,
              activeMemberSegment?.sortKey ?? column.id,
              activeMemberSegment?.label ?? column.header,
            )}
            hasBorder={false}
            activeFill={false}
            isActive={true}
            pressScale={false}
            data-sort-control="direction"
            onDsClick={() => this.emitSort(column, activeMemberSegment?.sortKey ?? column.id)}
          />
        )}
      </span>
    ) : null;
    const collapseHost = model.collapseAllHost;
    const actionCollapseHost = collapseHost?.mode === 'action' && collapseHost.columnId === column.id;
    const blankActionCollapseHost = actionCollapseHost &&
      !column.header.trim() &&
      !column.headerSegments?.length;
    const collapseControl =
      interactive && actionCollapseHost ? (
        <span class="ds-table__collapse-slot">
          {this.renderCollapseAllButton()}
        </span>
      ) : null;

    return (
      <th
        key={column.id}
        class={{
          'ds-table__header-cell': true,
          [`ds-table__cell--align-${align}`]: true,
          'ds-table__cell--sticky-start': column.sticky === 'start',
          'ds-table__cell--sticky-end': column.sticky === 'end',
          'ds-table__header-cell--collapse-all': actionCollapseHost,
        }}
        scope={presentational ? undefined : 'col'}
        aria-sort={presentational ? undefined : memberAriaSort}
        data-column-id={column.id}
        data-grouped={groupedColumn ? 'true' : undefined}
        data-sort-active={activeSort ? 'true' : undefined}
      >
        {!column.header.trim() && column.headerLabel?.trim() && (
          <span class="ds-visually-hidden">{column.headerLabel}</span>
        )}
        {blankActionCollapseHost ? (
          <span class="ds-table__header-content ds-table__header-content--collapse-all">
            {collapseControl}
          </span>
        ) : (
          <span class="ds-table__header-content">
            {align === 'end' && sortControl}
            {align === 'center' && (
              <span
                class="ds-table__sort-slot ds-table__sort-slot--balance"
                data-sort-balance="true"
                aria-hidden="true"
              />
            )}
            {labelControl}
            {align !== 'end' && sortControl}
            {collapseControl}
          </span>
        )}
        {this.renderStickyEdge(column.sticky)}
      </th>
    );
  }

  private renderColgroup(model: TableRenderModel) {
    return (
      <colgroup>
        {model.selectable && <col class="ds-table__selection-column" />}
        {this.columns.map(column => {
          const width = tableColumnSize(column);
          const flexible = column.id === model.flexibleColumnId;
          return (
            <col
              key={column.id}
              class={{
                'ds-table__action-column': column.kind === 'action',
                'ds-table__flexible-column': flexible,
              }}
              style={width && !flexible ? { width } : undefined}
            />
          );
        })}
      </colgroup>
    );
  }

  private renderHeader(
    model: TableRenderModel,
    interactive = true,
    presentational = false,
  ) {
    const selection = model.selection;
    return (
      <thead class={{
        'ds-table__head': true,
        'ds-table__head--semantic-copy': !interactive,
      }} ref={element => {
        if (interactive) this.interactiveHeadEl = element ?? null;
      }}>
        <tr class="ds-table__header-row">
          {model.selectable && (
            <th
              class="ds-table__header-cell ds-table__selection-cell ds-table__cell--sticky-start"
              scope={presentational ? undefined : 'col'}
            >
              {interactive ? this.renderSelectionControl(
                selection.allSelected ? 'Deselect all loaded rows' : 'Select all loaded rows',
                selection.allSelected,
                selection.indeterminate,
                selection.selectableRowIds.length === 0,
                () => this.emitAllSelection(),
              ) : (
                <span class="ds-visually-hidden">Select rows</span>
              )}
              {this.renderStickyEdge('start')}
            </th>
          )}
          {this.columns.map(column => (
            this.renderColumnHeader(column, model, interactive, presentational)
          ))}
        </tr>
      </thead>
    );
  }

  private renderCellValue(
    cell: TableCellPresentation,
    column: TableColumn,
    row: TableRow,
  ) {
    if (cell.kind === 'blank') return null;

    if (cell.kind === 'empty') {
      return (
        <ds-text
          class="ds-table__cell-track ds-table__cell-track--text"
          as="span"
          variant="text-body-medium"
          color="secondary"
        >
          <span aria-hidden="true">—</span>
          <span class="ds-visually-hidden">{this.emptyCellLabel}</span>
        </ds-text>
      );
    }

    if (cell.kind === 'icon') {
      const value = cell.value;
      return (
        <ds-icon
          name={value.icon}
          size="md"
          color={value.color ?? 'secondary'}
          label={value.label}
        />
      );
    }

    if (cell.kind === 'image') {
      const value = cell.value;
      return (
        <span class="ds-table__cell-image">
          {value.src ? (
            <img class="ds-table__cell-image-content" src={value.src} alt={value.alt} loading="lazy" />
          ) : (
            <span
              class="ds-table__cell-image-placeholder"
              role="img"
              aria-label={value.alt}
            />
          )}
        </span>
      );
    }

    if (cell.kind === 'action') {
      const value = cell.value;
      return (
        <ds-button-unfilled
          variant={value.variant ?? 'label'}
          size="md"
          isInset={true}
          insetDepth="double"
          label={value.label ?? ''}
          icon={value.icon ?? ''}
          aria-label={value.ariaLabel ?? null}
          hasBorder={value.hasBorder ?? false}
          isInactive={value.isInactive ?? false}
          isLoading={value.isLoading ?? false}
          onDsClick={event => {
            event.stopPropagation();
            this.dsCellAction.emit({
              actionId: value.actionId,
              rowId: row.id,
              columnId: column.id,
            });
          }}
        />
      );
    }

    if (cell.kind === 'tag') {
      const value = cell.value;
      const variant = cell.variant;
      const tag = (
        <ds-tag
          label={value.label}
          intent={value.intent ?? 'neutral'}
          contrast={value.contrast ?? 'faint'}
          size={variant === 'text-with-tag' ? 'sm' : 'md'}
          icon={value.icon ?? ''}
          rounded={value.rounded ?? false}
          isInset
          insetDepth="double"
        />
      );

      if (variant === 'tag-only') return tag;

      return (
        <span class={`ds-table__cell-tag-stack ds-table__cell-tag-stack--${variant}`}>
          {variant === 'tag-with-text' && tag}
          <ds-text
            class="ds-table__cell-tag-text ds-table__cell-track"
            as="span"
            variant={variant === 'tag-with-text' ? 'text-body-small' : 'text-body-medium'}
            color="secondary"
            lineTruncation={1}
          >
            {value.text}
          </ds-text>
          {variant === 'text-with-tag' && (
            <span class="ds-table__cell-tag-control-track">{tag}</span>
          )}
        </span>
      );
    }

    const text = cell.value;
    const wraps = cell.wraps;

    return (
      <span class={{ 'ds-table__cell-copy': true, 'ds-table__cell-copy--wrap': wraps }}>
        <ds-text
          class="ds-table__cell-primary ds-table__cell-track ds-table__cell-track--text"
          as="span"
          variant="text-body-medium"
          color="primary"
          lineTruncation={wraps ? 'none' : 1}
          wrap={wraps ? 'wrap' : 'nowrap'}
          fontFeature={text.fontFeature ?? 'normal'}
        >
          {text.primary}
        </ds-text>
        {text.secondary !== undefined && text.secondary !== '' && (
          <ds-text
            class="ds-table__cell-secondary ds-table__cell-track ds-table__cell-track--text"
            as="span"
            variant={cell.primaryText ? 'text-body-medium' : 'text-body-small'}
            color={cell.primaryText ? 'primary' : 'secondary'}
            lineTruncation={wraps ? 'none' : 1}
            wrap={wraps ? 'wrap' : 'nowrap'}
          >
            {text.secondary}
          </ds-text>
        )}
      </span>
    );
  }

  private renderRow(row: TableRow, model: TableRenderModel) {
    const selected = model.selectedRowIds.has(row.id);
    const rowSelectable = row.selectable !== false && !row.disabled;
    return (
      <tr
        key={row.id}
        class={{
          'ds-table__row': true,
          'ds-table__row--selected': selected,
          'ds-table__row--disabled': !!row.disabled,
          'ds-table__row--interactive': !!row.interactive && !row.disabled,
        }}
        data-row-id={row.id}
        data-selected={selected ? 'true' : undefined}
        aria-disabled={row.disabled ? 'true' : undefined}
        tabIndex={row.interactive && !row.disabled ? 0 : undefined}
        onClick={event => this.emitRowActivation(row, event)}
        onKeyDown={event => this.handleRowKeydown(row, event)}
      >
        {model.selectable && (
          <td class={{
            'ds-table__cell': true,
            'ds-table__selection-cell': true,
            'ds-table__cell--sticky-start': true,
            'ds-interaction-fill': true,
            'ds-interaction-fill--grouped': true,
            'ds-interaction-fill--selected': selected,
          }}>
            {this.renderSelectionControl(
              `${selected ? 'Deselect' : 'Select'} ${tableRowSelectionLabel(row, this.columns)}`,
              selected,
              false,
              !rowSelectable,
              () => this.emitRowSelection(row),
            )}
            {this.renderStickyEdge('start')}
          </td>
        )}
        {this.columns.map(column => {
          const align = column.align ?? 'start';
          const cell = resolveTableCellPresentation(row.cells[column.id], column);
          const tagCell = cell.kind === 'tag';
          const iconCell = cell.kind === 'icon';
          const imageCell = cell.kind === 'image';
          const actionCell = cell.kind === 'action';
          const textCell = cell.kind === 'text';
          const primaryTextCell = textCell && cell.primaryText;
          const singleTextCell = textCell && cell.singleLine;
          const emptyCell = cell.kind === 'empty';
          const blankCell = cell.kind === 'blank';
          const tagVariant = tagCell ? cell.variant : undefined;
          const textVariant = textCell ? cell.variant : undefined;
          return (
            <td
              key={`${row.id}:${column.id}`}
              class={{
                'ds-table__cell': true,
                [`ds-table__cell--align-${align}`]: true,
                'ds-table__cell--tag': tagCell,
                [`ds-table__cell--tag-${tagVariant}`]: tagCell,
                'ds-table__cell--icon': iconCell,
                'ds-table__cell--image': imageCell,
                'ds-table__cell--action': actionCell,
                'ds-table__cell--primary-text': primaryTextCell,
                'ds-table__cell--text-single': singleTextCell,
                'ds-table__cell--text-multi': textCell && !singleTextCell,
                'ds-table__cell--empty': emptyCell,
                'ds-table__cell--blank': blankCell,
                'ds-table__cell--sticky-start': column.sticky === 'start',
                'ds-table__cell--sticky-end': column.sticky === 'end',
                'ds-interaction-fill': true,
                'ds-interaction-fill--grouped': true,
                'ds-interaction-fill--selected': selected,
              }}
              data-column-id={column.id}
              data-cell-type={cell.cellType}
              data-cell-variant={tagVariant ?? textVariant}
            >
              <span class="ds-table__cell-content ds-interaction-fill__content">
                {this.renderCellValue(cell, column, row)}
              </span>
              {this.renderStickyEdge(column.sticky)}
            </td>
          );
        })}
      </tr>
    );
  }

  private emitGroupCollapse(group: TableGroup) {
    const collapsedGroupIds = toggleTableGroupCollapsed(this.collapsedGroupIds, group.id);
    this.dsGroupCollapseChange.emit({
      scope: 'group',
      groupId: group.id,
      collapsed: collapsedGroupIds.includes(group.id),
      collapsedGroupIds,
    });
  }

  private emitAllGroupsCollapse() {
    const groupIds = this.groups.map(group => group.id);
    const collapsedGroupIds = nextTableGroupsCollapsed(this.collapsedGroupIds, groupIds);
    this.dsGroupCollapseChange.emit({
      scope: 'all',
      collapsed: collapsedGroupIds.length > 0,
      collapsedGroupIds,
    });
  }

  private renderDataBodies(model: TableRenderModel) {
    if (!model.grouped) {
      return (
        <tbody class="ds-table__body">
          {this.rows.map(row => this.renderRow(row, model))}
        </tbody>
      );
    }

    return model.groups.map(groupModel => {
      const {
        group,
        count,
        countLabel,
        countIntent,
        collapsed: isCollapsed,
        intent,
        intentClass,
        labelColor,
        selection: groupSelection,
      } = groupModel;
      return (
        <tbody
          class="ds-table__body ds-table__group"
          data-group-id={group.id}
          data-group-intent={intent}
          data-collapsed={isCollapsed ? 'true' : undefined}
          key={group.id}
        >
          <tr class="ds-table__group-row">
            <th
              class={{
                'ds-table__group-cell': true,
                [intentClass ?? '']: !!intentClass,
              }}
              scope="rowgroup"
              colSpan={model.totalColumns}
            >
              <span class="ds-table__group-content">
                {groupSelection && (
                  <span class="ds-table__group-selection">
                    {this.renderSelectionControl(
                      groupSelection.allSelected
                        ? `Deselect ${group.label} group`
                        : `Select ${group.label} group`,
                      groupSelection.allSelected,
                      groupSelection.indeterminate,
                      groupSelection.selectableRowIds.length === 0,
                      () => this.emitGroupSelection(group),
                    )}
                  </span>
                )}
                <span class="ds-table__group-copy">
                  <ds-text
                    class="ds-table__group-label"
                    as="span"
                    variant="text-body-medium"
                    emphasis={true}
                    color={labelColor}
                  >
                    {group.label}
                  </ds-text>
                  <span
                    class="ds-table__group-count ds-control-elevation ds-control-elevation--sm"
                    aria-hidden="true"
                  >
                    <ds-tag
                      label={String(count)}
                      intent={countIntent}
                      contrast="faint"
                      size="sm"
                      rounded={true}
                    ></ds-tag>
                  </span>
                  <span class="ds-visually-hidden">{countLabel}</span>
                </span>
                <ds-button-unfilled
                  class="ds-table__group-toggle"
                  variant="icon"
                  size="md"
                  isInset={true}
                  insetDepth="double"
                  icon={isCollapsed ? 'ChevronDown' : 'ChevronUp'}
                  expanded={!isCollapsed}
                  aria-label={
                    isCollapsed
                      ? `Expand ${group.label} group`
                      : `Collapse ${group.label} group`
                  }
                  hasBorder={false}
                  onDsClick={event => {
                    event.stopPropagation();
                    this.emitGroupCollapse(group);
                  }}
                />
              </span>
            </th>
          </tr>
          {!isCollapsed && group.rows.map(row => this.renderRow(row, model))}
        </tbody>
      );
    });
  }

  private renderSkeletonBody(model: TableRenderModel) {
    const count = Math.min(20, Math.max(1, Math.round(this.skeletonRows) || 1));
    return (
      <tbody class="ds-table__body ds-table__skeleton-body">
        {Array.from({ length: count }, (_, index) => (
          <tr class="ds-table__row ds-table__skeleton-row" key={`skeleton-${index}`}>
            {model.selectable && (
              <td class="ds-table__cell ds-table__selection-cell ds-table__cell--sticky-start ds-table__skeleton-cell ds-interaction-fill ds-interaction-fill--grouped">
                <span class="ds-interaction-fill__content">
                  <ds-skeleton variant="icon" iconSize="md" />
                </span>
                {this.renderStickyEdge('start')}
              </td>
            )}
            {this.columns.map(column => (
              <td
                class={{
                  'ds-table__cell': true,
                  'ds-table__cell--text-single': true,
                  'ds-table__skeleton-cell': true,
                  'ds-table__cell--sticky-start': column.sticky === 'start',
                  'ds-table__cell--sticky-end': column.sticky === 'end',
                  'ds-interaction-fill': true,
                  'ds-interaction-fill--grouped': true,
                }}
                key={`skeleton-${index}:${column.id}`}
              >
                <span class="ds-table__cell-content ds-interaction-fill__content">
                  <ds-skeleton variant="text" textVariant="text-body-medium" width="100%" />
                </span>
                {this.renderStickyEdge(column.sticky)}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    );
  }

  private renderStateBody(kind: 'empty' | 'error', totalColumns: number) {
    const error = kind === 'error';
    return (
      <tbody class="ds-table__body ds-table__state-body">
        <tr class="ds-table__state-row">
          <td class="ds-table__state-cell" colSpan={totalColumns}>
            <ds-empty-state
              icon={error ? 'ErrorTriangle' : 'Inbox'}
              heading={error ? this.errorHeading : this.emptyHeading}
              body={error ? this.errorBody : this.emptyBody}
            />
          </td>
        </tr>
      </tbody>
    );
  }

  private renderLazyBody(model: TableRenderModel) {
    if (!this.lazyLoading || !model.hasData) return null;
    const error = this.loadMoreError?.trim();
    const manualFallback = this.loadMoreMode === 'manual' ||
      !this.loadController.intersectionSupported;

    return (
      <tbody class="ds-table__body ds-table__load-body">
        <tr
          class="ds-table__load-row"
          ref={element => {
            this.sentinelEl = element ?? null;
          }}
        >
          <td class="ds-table__load-cell" colSpan={model.totalColumns}>
            {error ? (
              <span class="ds-table__load-content ds-table__load-content--error">
                <span class="ds-table__load-copy">
                  <ds-icon name="ErrorTriangle" size="md" color="secondary" aria-hidden="true" />
                  <ds-text as="span" variant="text-body-medium" color="secondary">{error}</ds-text>
                </span>
                <ds-button-unfilled
                  label={this.retryLabel}
                  size="md"
                  onDsClick={() => this.loadController.request('retry')}
                />
              </span>
            ) : this.loadingMore ? (
              <span class="ds-table__load-content">
                <ds-loader size="md" color="secondary" />
                <ds-text as="span" variant="text-body-medium" color="secondary">
                  {this.loadingMoreLabel}
                </ds-text>
              </span>
            ) : this.hasMore && manualFallback ? (
              <span class="ds-table__load-content">
                <ds-button-unfilled
                  label={this.loadMoreLabel}
                  size="md"
                  onDsClick={() => this.loadController.request('manual')}
                />
              </span>
            ) : this.hasMore ? (
              <span class="ds-table__auto-sentinel" aria-hidden="true" />
            ) : (
              <ds-text
                class="ds-table__load-content"
                as="span"
                variant="text-body-medium"
                color="secondary"
              >
                {this.endOfResultsLabel}
              </ds-text>
            )}
          </td>
        </tr>
      </tbody>
    );
  }

  private renderDocumentStickyHeader(model: TableRenderModel) {
    if (!this.documentStickyHeader) return null;
    return (
      <div
        class="ds-table__document-sticky-header"
      >
        <table
          class={{
            'ds-table__table': true,
            'ds-table__sticky-header-table': true,
            'ds-table__table--selectable': model.selectable,
            'ds-table__table--grouped': model.grouped,
          }}
          style={model.tableStyle}
          role="presentation"
          ref={element => {
            this.stickyHeaderTableEl = element ?? null;
          }}
        >
          {this.renderColgroup(model)}
          {this.renderHeader(model, true, true)}
        </table>
        {this.renderFloatingCollapseAll(model)}
      </div>
    );
  }

  private get resultSummary(): string | null {
    return formatTableResultSummary(
      this.displayedCount,
      this.totalCount,
      this.resultSummaryLabel,
    );
  }

  private renderResultFooter() {
    const summary = this.resultSummary;
    if (!summary) return null;
    return (
      <ds-text
        class="ds-table__footer"
        as="div"
        variant="text-body-medium"
        color="secondary"
      >
        {summary}
      </ds-text>
    );
  }

  private renderCaptionBar() {
    if (this.captionVisibility !== 'visible') return null;
    return (
      <ds-text
        class="ds-table__caption-bar"
        as="div"
        variant="text-title-small"
        emphasis={true}
        color="primary"
        aria-hidden="true"
      >
        {this.caption}
      </ds-text>
    );
  }

  render() {
    const model = this.createRenderModel();
    this.renderedModel = model;
    const regionLabel = this.scrollLabel?.trim() || `${this.caption} scroll area`;
    const initialLoading = this.loading && !model.hasData;
    const initialError = !model.hasData && this.error;
    const viewportStyle = this.resolvedMaxHeight
      ? { '--ds-table-max-block-size': this.resolvedMaxHeight }
      : undefined;

    return (
      <Host class="table-host">
        <div class={{
          'ds-table': true,
          'ds-table--sticky-header': this.stickyHeader,
          'ds-table--document-sticky-header': this.documentStickyHeader,
          'ds-table--contained-sticky-header': this.stickyHeader && !this.documentStickyHeader,
        }}>
          {this.renderCaptionBar()}
          <div
            class={{
              'ds-table__frame': true,
              'ds-table__frame--overflow-start': this.overflowStart,
              'ds-table__frame--overflow-end': this.overflowEnd,
            }}
            ref={element => {
              this.frameEl = element ?? null;
            }}
          >
            {this.renderDocumentStickyHeader(model)}
            {!this.documentStickyHeader && this.renderFloatingCollapseAll(model)}
            <div
              class="ds-table__viewport"
              style={viewportStyle}
              ref={element => {
                this.viewportEl = element ?? null;
              }}
              role={this.scrollable ? 'region' : undefined}
              aria-label={this.scrollable ? regionLabel : undefined}
              tabIndex={this.scrollable ? 0 : undefined}
            >
              <table
                class={{
                  'ds-table__table': true,
                  'ds-table__table--selectable': model.selectable,
                  'ds-table__table--grouped': model.grouped,
                }}
                style={model.tableStyle}
                aria-busy={initialLoading || this.loadingMore ? 'true' : undefined}
                ref={element => {
                  this.tableEl = element ?? null;
                }}
              >
                <caption class="ds-table__caption ds-visually-hidden">
                  <ds-text as="span" variant="text-title-small" emphasis={true} color="primary">
                    {this.caption}
                  </ds-text>
                </caption>
                {this.renderColgroup(model)}
                {this.renderHeader(model, !this.documentStickyHeader)}
                {initialLoading
                  ? this.renderSkeletonBody(model)
                  : initialError
                    ? this.renderStateBody('error', model.totalColumns)
                    : model.hasData
                      ? this.renderDataBodies(model)
                      : this.renderStateBody('empty', model.totalColumns)}
                {!initialLoading && !initialError && this.renderLazyBody(model)}
              </table>
            </div>
          </div>
          {this.renderResultFooter()}
          <div class="ds-visually-hidden" role="status" aria-live="polite" aria-atomic="true">
            {this.announcement}
          </div>
        </div>
      </Host>
    );
  }
}

import {
  isTableCellAction,
  isTableCellBlank,
  isTableCellEmpty,
  isTableCellIcon,
  isTableCellImage,
  isTableCellPrimaryText,
  isTableCellTag,
  isTableCellText,
} from './table-model';
import type {
  TableCellAction,
  TableCellBlank,
  TableCellEmpty,
  TableCellIcon,
  TableCellImage,
  TableCellTag,
  TableCellTagVariant,
  TableCellValue,
  TableColumn,
} from './table-types';

export interface ResolvedTableCellText {
  primary: string | number;
  secondary?: string | number;
  wrap?: boolean;
  fontFeature?: 'normal' | 'tabular-nums';
}

export type TableCellPresentation =
  | { kind: 'blank'; cellType: 'blank'; value: TableCellBlank }
  | { kind: 'empty'; cellType: 'empty'; value: TableCellEmpty | null | undefined }
  | { kind: 'icon'; cellType: 'icon'; value: TableCellIcon }
  | { kind: 'image'; cellType: 'image'; value: TableCellImage }
  | { kind: 'action'; cellType: 'action'; value: TableCellAction }
  | {
      kind: 'tag';
      cellType: 'tag';
      value: TableCellTag;
      variant: TableCellTagVariant;
    }
  | {
      kind: 'text';
      cellType: 'text' | 'primary-text';
      value: ResolvedTableCellText;
      primaryText: boolean;
      singleLine: boolean;
      variant: 'single' | 'multi' | 'primary-pair';
      wraps: boolean;
    };

/** Resolve a cell's semantic and visual recipe once for both markup and classes. */
export function resolveTableCellPresentation(
  value: TableCellValue,
  column: TableColumn,
): TableCellPresentation {
  if (isTableCellBlank(value)) return { kind: 'blank', cellType: 'blank', value };
  if (value == null || isTableCellEmpty(value)) {
    return { kind: 'empty', cellType: 'empty', value };
  }
  if (isTableCellIcon(value)) return { kind: 'icon', cellType: 'icon', value };
  if (isTableCellImage(value)) return { kind: 'image', cellType: 'image', value };
  if (isTableCellAction(value)) return { kind: 'action', cellType: 'action', value };
  if (isTableCellTag(value)) {
    return {
      kind: 'tag',
      cellType: 'tag',
      value,
      variant: value.variant ?? 'tag-only',
    };
  }

  const primaryText = isTableCellPrimaryText(value);
  const text: ResolvedTableCellText = isTableCellText(value) || primaryText
    ? value
    : {
        primary: value,
        fontFeature: typeof value === 'number' ? 'tabular-nums' : 'normal',
      };
  const singleLine = !primaryText && (text.secondary === undefined || text.secondary === '');
  return {
    kind: 'text',
    cellType: primaryText ? 'primary-text' : 'text',
    value: text,
    primaryText,
    singleLine,
    variant: primaryText ? 'primary-pair' : singleLine ? 'single' : 'multi',
    wraps: text.wrap ?? column.wrap ?? false,
  };
}

export interface TableLayoutElements {
  viewport: HTMLElement | null;
  table: HTMLTableElement | null;
  stickyHeaderTable: HTMLTableElement | null;
  collapseAllOverlay: HTMLElement | null;
  frame: HTMLElement | null;
  interactiveHead: HTMLTableSectionElement | null;
}

export interface TableLayoutMode {
  documentStickyHeader: boolean;
  floatingCollapseAll: boolean;
}

export interface TableOverflowState {
  start: boolean;
  end: boolean;
  scrollable: boolean;
}

export interface TableLayoutControllerOptions {
  elements: () => TableLayoutElements;
  mode: () => TableLayoutMode;
  overflowChanged: (state: TableOverflowState) => void;
}

export interface TableLayoutMetricInput {
  viewportInlineSize: number;
  viewportBlockSize: number;
  scrollInlineSize: number;
  scrollBlockSize: number;
  scrollInlineOffset: number;
  tableInlineSize: number;
  collapseHeadBlockStart?: number;
  collapseFrameBlockStart?: number;
}

export interface TableLayoutMetrics {
  visibleInlineSize: number;
  overflow: TableOverflowState;
  inlineOffset: number;
  maxInlineOffset: number;
  collapseBlockOffset: number | null;
}

/** Pure geometry resolution shared by the controller and focused tests. */
export function resolveTableLayoutMetrics(input: TableLayoutMetricInput): TableLayoutMetrics {
  const horizontalOverflow = input.scrollInlineSize - input.viewportInlineSize > 1;
  return {
    visibleInlineSize: Math.min(input.viewportInlineSize, input.tableInlineSize),
    overflow: {
      start: horizontalOverflow && input.scrollInlineOffset > 1,
      end: horizontalOverflow &&
        input.scrollInlineOffset + input.viewportInlineSize < input.scrollInlineSize - 1,
      scrollable: horizontalOverflow || input.scrollBlockSize - input.viewportBlockSize > 1,
    },
    inlineOffset: input.scrollInlineOffset,
    maxInlineOffset: Math.max(0, input.scrollInlineSize - input.viewportInlineSize),
    collapseBlockOffset: input.collapseHeadBlockStart == null ||
      input.collapseFrameBlockStart == null
      ? null
      : Math.max(0, input.collapseHeadBlockStart - input.collapseFrameBlockStart),
  };
}

/**
 * Owns table viewport observation. It resolves newly rendered geometry
 * immediately so the first paint has the correct viewport-width chrome, then
 * batches observer-driven scroll and resize reads/writes into one animation frame.
 * The component remains responsible only for refs and reactive overflow state.
 */
export class TableLayoutController {
  private connected = false;
  private connectedViewport: HTMLElement | null = null;
  private observedTable: HTMLTableElement | null = null;
  private resizeObserver: ResizeObserver | null = null;
  private frame: number | null = null;
  private overflow: TableOverflowState | null = null;

  constructor(private readonly options: TableLayoutControllerOptions) {}

  connect(): void {
    this.connected = true;
    this.refresh();
  }

  disconnect(): void {
    this.connected = false;
    if (this.frame !== null) cancelAnimationFrame(this.frame);
    this.frame = null;
    this.connectedViewport?.removeEventListener('scroll', this.schedule);
    this.connectedViewport = null;
    this.observedTable = null;
    this.resizeObserver?.disconnect();
    this.resizeObserver = null;
  }

  /** Reconcile newly rendered refs, observers, and pending geometry. */
  refresh(): void {
    if (!this.connected) return;
    const { viewport, table } = this.options.elements();
    const elementsChanged = viewport !== this.connectedViewport || table !== this.observedTable;
    if (elementsChanged) {
      this.connectedViewport?.removeEventListener('scroll', this.schedule);
      this.resizeObserver?.disconnect();
      this.connectedViewport = viewport;
      this.observedTable = table;
      viewport?.addEventListener('scroll', this.schedule, { passive: true });

      if (typeof ResizeObserver !== 'undefined' && viewport) {
        this.resizeObserver ??= new ResizeObserver(this.schedule);
        this.resizeObserver.observe(viewport);
        if (table) this.resizeObserver.observe(table);
      }
    }
    // Rendering can change the table's intrinsic width without replacing either
    // element. Resolve that geometry before componentDidRender returns so WebKit
    // cannot paint or expose one frame using the full spanning-cell width.
    this.sync();
  }

  private schedule = (): void => {
    if (!this.connected || this.frame !== null) return;
    this.frame = requestAnimationFrame(() => {
      this.frame = null;
      this.sync();
    });
  };

  private sync(): void {
    const elements = this.options.elements();
    const viewport = elements.viewport;
    if (!viewport) return;

    // Read every layout value before writing styles or reactive state.
    const mode = this.options.mode();
    const measureCollapse = mode.floatingCollapseAll && !mode.documentStickyHeader &&
      elements.collapseAllOverlay && elements.frame && elements.interactiveHead;
    const metrics = resolveTableLayoutMetrics({
      viewportInlineSize: viewport.clientWidth,
      viewportBlockSize: viewport.clientHeight,
      scrollInlineSize: viewport.scrollWidth,
      scrollBlockSize: viewport.scrollHeight,
      scrollInlineOffset: viewport.scrollLeft,
      tableInlineSize: elements.table?.getBoundingClientRect().width ?? viewport.clientWidth,
      collapseHeadBlockStart: measureCollapse
        ? elements.interactiveHead!.getBoundingClientRect().top
        : undefined,
      collapseFrameBlockStart: measureCollapse
        ? elements.frame!.getBoundingClientRect().top
        : undefined,
    });

    this.setProperty(
      viewport,
      '--ds-table-visible-inline-size',
      `${metrics.visibleInlineSize}px`,
    );
    if (elements.stickyHeaderTable) {
      this.setProperty(
        elements.stickyHeaderTable,
        '--ds-table-inline-scroll-offset',
        `${metrics.inlineOffset}px`,
      );
      this.setProperty(
        elements.stickyHeaderTable,
        '--ds-table-inline-scroll-max-offset',
        `${metrics.maxInlineOffset}px`,
      );
    }
    if (metrics.collapseBlockOffset !== null && elements.collapseAllOverlay) {
      this.setProperty(
        elements.collapseAllOverlay,
        '--ds-table-collapse-all-block-offset',
        `${metrics.collapseBlockOffset}px`,
      );
    }

    if (
      !this.overflow ||
      this.overflow.start !== metrics.overflow.start ||
      this.overflow.end !== metrics.overflow.end ||
      this.overflow.scrollable !== metrics.overflow.scrollable
    ) {
      this.overflow = metrics.overflow;
      this.options.overflowChanged(metrics.overflow);
    }
  }

  private setProperty(element: HTMLElement, property: string, value: string): void {
    if (element.style.getPropertyValue(property) !== value) {
      element.style.setProperty(property, value);
    }
  }
}

import type {
  TableLoadMoreDetail,
  TableLoadMoreMode,
  TableLoadMoreReason,
} from './table-types';

export interface TableLoadControllerState {
  lazyLoading: boolean;
  loadMoreMode: TableLoadMoreMode;
  hasMore: boolean;
  loadingMore: boolean;
  loadMoreError: string | undefined;
  loadIdentity: string | number;
  loadMoreThreshold: number;
  containedScroll: boolean;
  loadingMoreLabel: string;
  endOfResultsLabel: string;
  rowsLoadedLabel: string;
  loadedRowCount: number;
  viewport: HTMLElement | null;
  sentinel: HTMLElement | null;
}

export interface TableLoadControllerOptions {
  state: () => TableLoadControllerState;
  announce: (message: string) => void;
  request: (detail: TableLoadMoreDetail) => void;
}

/** Owns incremental-loading request guards, announcements, and observation. */
export class TableLoadController {
  readonly intersectionSupported = typeof IntersectionObserver !== 'undefined';

  private connected = false;
  private intersectionObserver: IntersectionObserver | null = null;
  private observedSentinel: HTMLElement | null = null;
  private requestPending = false;
  private requestedRowCount = 0;
  private previousLoadedRowCount = 0;

  constructor(private readonly options: TableLoadControllerOptions) {}

  initialize(): void {
    this.previousLoadedRowCount = this.options.state().loadedRowCount;
  }

  connect(): void {
    this.connected = true;
    this.refresh();
  }

  disconnect(): void {
    this.connected = false;
    this.disconnectObserver();
  }

  refresh(): void {
    if (!this.connected) return;
    const state = this.options.state();
    if (
      !state.lazyLoading ||
      state.loadMoreMode !== 'auto' ||
      !state.hasMore ||
      !!state.loadMoreError?.trim() ||
      !this.intersectionSupported ||
      !state.viewport ||
      !state.sentinel
    ) {
      this.disconnectObserver();
      return;
    }

    if (this.intersectionObserver && this.observedSentinel === state.sentinel) return;
    this.disconnectObserver();
    const threshold = Number.isFinite(state.loadMoreThreshold)
      ? Math.max(0, state.loadMoreThreshold)
      : 0;
    this.intersectionObserver = new IntersectionObserver(
      entries => {
        if (entries.some(entry => entry.isIntersecting)) this.request('auto');
      },
      {
        root: state.containedScroll ? state.viewport : null,
        rootMargin: `0px 0px ${threshold}px 0px`,
      },
    );
    this.observedSentinel = state.sentinel;
    this.intersectionObserver.observe(state.sentinel);
  }

  structureChanged(): void {
    this.resetRequest();
  }

  dataChanged(): void {
    const state = this.options.state();
    const nextCount = state.loadedRowCount;
    if (nextCount > this.previousLoadedRowCount) {
      const added = nextCount - this.previousLoadedRowCount;
      this.options.announce(
        state.rowsLoadedLabel
          .replace('{count}', String(added))
          .replace('{total}', String(nextCount)),
      );
    }
    if (nextCount > this.requestedRowCount) this.requestPending = false;
    this.previousLoadedRowCount = nextCount;
    this.disconnectObserver();
  }

  identityChanged(): void {
    this.previousLoadedRowCount = this.options.state().loadedRowCount;
    this.resetRequest();
  }

  configurationChanged(): void {
    this.disconnectObserver();
  }

  loadingChanged(loading: boolean): void {
    const state = this.options.state();
    if (loading) {
      this.requestPending = true;
      this.options.announce(state.loadingMoreLabel);
    } else if (state.loadMoreMode === 'manual') {
      // A completed manual request may append no rows; permit another explicit activation.
      this.requestPending = false;
    }
    this.disconnectObserver();
  }

  errorChanged(error: string | undefined): void {
    if (error?.trim()) {
      this.requestPending = false;
      this.options.announce(error);
    }
    this.disconnectObserver();
  }

  hasMoreChanged(hasMore: boolean, hadMore: boolean): void {
    if (!hasMore) {
      this.requestPending = false;
      if (hadMore) this.options.announce(this.options.state().endOfResultsLabel);
    }
    this.disconnectObserver();
  }

  request(reason: TableLoadMoreReason): void {
    const state = this.options.state();
    if (
      !state.lazyLoading ||
      !state.hasMore ||
      state.loadingMore ||
      (reason !== 'retry' && !!state.loadMoreError?.trim()) ||
      this.requestPending
    ) return;

    this.requestPending = true;
    this.requestedRowCount = state.loadedRowCount;
    this.options.announce(state.loadingMoreLabel);
    this.options.request({
      reason,
      loadIdentity: state.loadIdentity,
      loadedRowCount: this.requestedRowCount,
    });
  }

  private resetRequest(): void {
    this.requestPending = false;
    this.requestedRowCount = this.options.state().loadedRowCount;
    this.disconnectObserver();
  }

  private disconnectObserver(): void {
    this.intersectionObserver?.disconnect();
    this.intersectionObserver = null;
    this.observedSentinel = null;
  }
}

import type {
  TableCellBlank,
  TableCellAction,
  TableCellEmpty,
  TableCellIcon,
  TableCellImage,
  TableCellPrimaryText,
  TableCellText,
  TableCellTag,
  TableCellValue,
  TableColumn,
  TableGroup,
  TableGroupingState,
  TableRow,
  TableSortState,
} from './table-types';

export interface TableSelectionState {
  selectableRowIds: string[];
  selectedLoadedCount: number;
  allSelected: boolean;
  indeterminate: boolean;
}

const TABLE_COLUMN_WIDTH_TOKENS = {
  xs: '--dimension-table-column-width-xs',
  sm: '--dimension-table-column-width-sm',
  md: '--dimension-table-column-width-md',
  lg: '--dimension-table-column-width-lg',
  xl: '--dimension-table-column-width-xl',
} as const;

export function isTableCellText(value: TableCellValue): value is TableCellText {
  return typeof value === 'object' && value !== null && 'primary' in value && !('kind' in value);
}

export function isTableCellPrimaryText(value: TableCellValue): value is TableCellPrimaryText {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'primary-text';
}

export function isTableCellTag(value: TableCellValue): value is TableCellTag {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'tag';
}

export function isTableCellIcon(value: TableCellValue): value is TableCellIcon {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'icon';
}

export function isTableCellImage(value: TableCellValue): value is TableCellImage {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'image';
}

export function isTableCellAction(value: TableCellValue): value is TableCellAction {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'action';
}

export function isTableCellEmpty(value: TableCellValue): value is TableCellEmpty {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'empty';
}

export function isTableCellBlank(value: TableCellValue): value is TableCellBlank {
  return typeof value === 'object' && value !== null && 'kind' in value && value.kind === 'blank';
}

export function tableCellPrimary(value: TableCellValue): string | number | null {
  if (value == null) return null;
  if (isTableCellTag(value)) return value.label;
  if (isTableCellIcon(value)) return null;
  if (isTableCellImage(value)) return value.alt;
  if (isTableCellAction(value)) return value.label ?? value.ariaLabel;
  if (isTableCellPrimaryText(value)) return value.primary;
  if (isTableCellEmpty(value) || isTableCellBlank(value)) return null;
  return isTableCellText(value) ? value.primary : value;
}

export function tableRowSelectionLabel(row: TableRow, columns: TableColumn[]): string {
  const explicit = row.selectionLabel?.trim();
  if (explicit) return explicit;

  for (const column of columns) {
    const primary = tableCellPrimary(row.cells[column.id]);
    if (primary != null && String(primary).trim()) return String(primary);
  }

  return row.id;
}

export function nextTableSortState(
  current: TableSortState | null | undefined,
  columnId: string,
): TableSortState {
  if (current?.columnId !== columnId) return { columnId, direction: 'asc' };
  if (current.direction === 'asc') return { columnId, direction: 'desc' };
  return { columnId, direction: 'asc' };
}

export function nextTableGroupOrder(grouping: TableGroupingState): TableGroupingState {
  return {
    ...grouping,
    direction: grouping.direction === 'asc' ? 'desc' : 'asc',
  };
}

export function toggleTableGroupCollapsed(
  collapsedGroupIds: string[],
  groupId: string,
): string[] {
  const next = new Set(collapsedGroupIds);
  if (next.has(groupId)) next.delete(groupId);
  else next.add(groupId);
  return [...next];
}

export function nextTableGroupsCollapsed(
  collapsedGroupIds: string[],
  groupIds: string[],
): string[] {
  if (groupIds.length === 0) return [];
  const collapsed = new Set(collapsedGroupIds);
  const allCollapsed = groupIds.every(id => collapsed.has(id));
  return allCollapsed ? [] : [...groupIds];
}

/** Host for grouped collapse-all: the trailing action lane or a scrollport-owned overlay. */
export type TableCollapseAllHost =
  | { columnId: string; mode: 'action' }
  | { mode: 'floating' };

export function tableCollapseAllHost(
  columns: TableColumn[],
): TableCollapseAllHost | undefined {
  if (columns.length === 0) return undefined;
  for (let index = columns.length - 1; index >= 0; index -= 1) {
    const column = columns[index]!;
    if (column.kind === 'action') return { columnId: column.id, mode: 'action' };
  }
  return { mode: 'floating' };
}

export function clampTableColumnSize(column: TableColumn): number | undefined {
  if (typeof column.size !== 'number' || !Number.isFinite(column.size) || column.size <= 0) {
    return undefined;
  }

  const minimum = Number.isFinite(column.minSize) && (column.minSize ?? 0) > 0
    ? column.minSize!
    : 0;
  const maximum = Number.isFinite(column.maxSize) && (column.maxSize ?? 0) > 0
    ? Math.max(column.maxSize!, minimum)
    : Number.POSITIVE_INFINITY;

  return Math.min(Math.max(column.size!, minimum), maximum);
}

export function tableColumnSize(column: TableColumn): string | undefined {
  if (typeof column.size === 'string') {
    return `var(${TABLE_COLUMN_WIDTH_TOKENS[column.size]})`;
  }
  const width = clampTableColumnSize(column);
  if (width != null) return `${width}px`;
  return column.kind === 'action' ? 'var(--dimension-size-500)' : undefined;
}

/**
 * When every column has an explicit width, one ordinary lane must absorb spare
 * table width so fixed selection and action lanes are not expanded by the
 * native fixed-table layout algorithm.
 */
export function tableFlexibleColumnId(columns: TableColumn[]): string | undefined {
  if (columns.some(column => !tableColumnSize(column))) return undefined;
  for (let index = columns.length - 1; index >= 0; index -= 1) {
    const column = columns[index]!;
    if (column.kind !== 'action' && !column.sticky) return column.id;
  }
  for (let index = columns.length - 1; index >= 0; index -= 1) {
    const column = columns[index]!;
    if (column.kind !== 'action') return column.id;
  }
  return columns[columns.length - 1]?.id;
}

export function tableExplicitMinWidth(columns: TableColumn[]): string | undefined {
  const widths = columns.map(tableColumnSize).filter((width): width is string => !!width);
  if (widths.length === 0) return undefined;
  return widths.length === 1 ? widths[0] : `calc(${widths.join(' + ')})`;
}

export function tableRows(rows: TableRow[], groups: TableGroup[], grouped: boolean): TableRow[] {
  return grouped ? groups.flatMap(group => group.rows) : rows;
}

function canSelectRow(row: TableRow): boolean {
  return row.selectable !== false && !row.disabled;
}

export function deriveTableSelectionState(
  rows: TableRow[],
  selectedRowIds: readonly string[],
): TableSelectionState {
  const selected = new Set(selectedRowIds);
  const selectableRowIds = rows.filter(canSelectRow).map(row => row.id);
  const selectedLoadedCount = selectableRowIds.reduce(
    (count, id) => count + (selected.has(id) ? 1 : 0),
    0,
  );

  return {
    selectableRowIds,
    selectedLoadedCount,
    allSelected: selectableRowIds.length > 0 && selectedLoadedCount === selectableRowIds.length,
    indeterminate: selectedLoadedCount > 0 && selectedLoadedCount < selectableRowIds.length,
  };
}

export function toggleTableRowSelection(
  selectedRowIds: readonly string[],
  row: TableRow,
): string[] {
  if (!canSelectRow(row)) return [...selectedRowIds];
  const selected = new Set(selectedRowIds);
  if (selected.has(row.id)) selected.delete(row.id);
  else selected.add(row.id);
  return [...selected];
}

export function toggleAllLoadedTableRows(
  selectedRowIds: readonly string[],
  loadedRows: TableRow[],
): string[] {
  const selected = new Set(selectedRowIds);
  const state = deriveTableSelectionState(loadedRows, selectedRowIds);

  for (const id of state.selectableRowIds) {
    if (state.allSelected) selected.delete(id);
    else selected.add(id);
  }

  return [...selected];
}

/** Toggle every selectable loaded row that belongs to a group. */
export function toggleTableGroupSelection(
  selectedRowIds: readonly string[],
  groupRows: TableRow[],
): string[] {
  return toggleAllLoadedTableRows(selectedRowIds, groupRows);
}

export function resolvedTableGroupCount(group: TableGroup): number {
  const total = Number.isFinite(group.totalCount) ? Math.max(0, group.totalCount!) : 0;
  return Math.max(total, group.rows.length);
}

export const TABLE_GROUP_INTENTS = [
  'brand',
  'neutral',
  'negative',
  'warning',
  'caution',
  'positive',
] as const;

export function isTableGroupIntent(
  value: unknown,
): value is (typeof TABLE_GROUP_INTENTS)[number] {
  return (
    typeof value === 'string' &&
    (TABLE_GROUP_INTENTS as readonly string[]).includes(value)
  );
}

export function tableGroupIntentClass(
  intent: (typeof TABLE_GROUP_INTENTS)[number] | undefined,
): string | undefined {
  return isTableGroupIntent(intent) ? `ds-table__group-cell--intent-${intent}` : undefined;
}

/** Title color for an intentful group label; defaults to primary when unset. */
export function tableGroupLabelColor(
  intent: (typeof TABLE_GROUP_INTENTS)[number] | undefined,
): 'primary' | 'brand' | 'negative' | 'warning' | 'caution' | 'positive' | `var(--${string})` {
  if (!isTableGroupIntent(intent)) return 'primary';
  if (intent === 'neutral') return 'var(--color-foreground-bold-neutral)';
  return intent;
}

/** Formats the optional table result footer. Returns null when either count is missing. */
export function formatTableResultSummary(
  displayed: number | null | undefined,
  total: number | null | undefined,
  label = 'Displaying {displayed} of {total}',
  locale?: string,
): string | null {
  if (!Number.isFinite(displayed) || !Number.isFinite(total)) return null;
  const formatter = new Intl.NumberFormat(locale);
  return label
    .replace('{displayed}', formatter.format(displayed as number))
    .replace('{total}', formatter.format(total as number));
}

export function tableModelIssues(
  columns: TableColumn[],
  rows: TableRow[],
  groups: TableGroup[],
  grouped: boolean,
): string[] {
  const issues: string[] = [];
  const columnIds = new Set<string>();
  for (const column of columns) {
    if (!column.id.trim()) issues.push('Every column requires a non-empty id.');
    else if (columnIds.has(column.id)) issues.push(`Duplicate column id: ${column.id}`);
    if (!column.header.trim() && !column.headerLabel?.trim()) {
      issues.push(`Column ${column.id || '(missing id)'} requires a visible header or headerLabel.`);
    }
    columnIds.add(column.id);
  }

  const groupIds = new Set<string>();
  if (grouped) {
    for (const group of groups) {
      if (!group.id.trim()) issues.push('Every group requires a non-empty id.');
      else if (groupIds.has(group.id)) issues.push(`Duplicate group id: ${group.id}`);
      groupIds.add(group.id);
      if (group.totalCount != null && group.totalCount < group.rows.length) {
        issues.push(`Group ${group.id} totalCount is smaller than its loaded row count.`);
      }
      if (group.intent != null && !isTableGroupIntent(group.intent)) {
        issues.push(`Group ${group.id} has an unsupported intent.`);
      }
    }
  }

  const rowIds = new Set<string>();
  for (const row of tableRows(rows, groups, grouped)) {
    if (!row.id.trim()) issues.push('Every row requires a non-empty id.');
    else if (rowIds.has(row.id)) issues.push(`Duplicate row id: ${row.id}`);
    rowIds.add(row.id);
  }

  return [...new Set(issues)];
}

import {
  deriveTableSelectionState,
  isTableGroupIntent,
  resolvedTableGroupCount,
  tableCollapseAllHost,
  tableExplicitMinWidth,
  tableFlexibleColumnId,
  tableGroupIntentClass,
  tableGroupLabelColor,
  tableRows,
  type TableCollapseAllHost,
  type TableSelectionState,
} from './table-model';
import type {
  TableColumn,
  TableGroup,
  TableGroupIntent,
  TableRow,
  TableSelectionMode,
} from './table-types';

export interface TableGroupRenderModel {
  group: TableGroup;
  count: number;
  countLabel: string;
  countIntent: TableGroupIntent;
  intent: TableGroupIntent | undefined;
  intentClass: string | undefined;
  labelColor: ReturnType<typeof tableGroupLabelColor>;
  collapsed: boolean;
  selection: TableSelectionState | null;
}

export interface TableRenderModel {
  grouped: boolean;
  selectable: boolean;
  loadedRows: TableRow[];
  hasData: boolean;
  selectedRowIds: ReadonlySet<string>;
  selection: TableSelectionState;
  collapsedGroupIds: ReadonlySet<string>;
  groups: TableGroupRenderModel[];
  totalColumns: number;
  allGroupsCollapsed: boolean;
  showCollapseAll: boolean;
  collapseAllHost: TableCollapseAllHost | undefined;
  flexibleColumnId: string | undefined;
  tableStyle: Record<string, string> | undefined;
}

export interface TableRenderModelInput {
  columns: TableColumn[];
  rows: TableRow[];
  groups: TableGroup[];
  grouped: boolean;
  selectionMode: TableSelectionMode;
  selectedRowIds: string[];
  collapsedGroupIds: string[];
}

/** Create one immutable snapshot of all derived state consumed during a render. */
export function createTableRenderModel(input: TableRenderModelInput): TableRenderModel {
  const selectable = input.selectionMode === 'multiple';
  const loadedRows = tableRows(input.rows, input.groups, input.grouped);
  const selectedRowIds = new Set(input.selectedRowIds);
  const collapsedGroupIds = new Set(input.collapsedGroupIds);
  const allGroupsCollapsed = input.grouped && input.groups.length > 0 &&
    input.groups.every(group => collapsedGroupIds.has(group.id));
  const showCollapseAll = input.grouped && input.groups.length > 0 && !allGroupsCollapsed;
  const explicitMinWidth = tableExplicitMinWidth(input.columns);

  return {
    grouped: input.grouped,
    selectable,
    loadedRows,
    hasData: loadedRows.length > 0,
    selectedRowIds,
    selection: deriveTableSelectionState(loadedRows, input.selectedRowIds),
    collapsedGroupIds,
    groups: input.groups.map(group => {
      const count = resolvedTableGroupCount(group);
      const intent = isTableGroupIntent(group.intent) ? group.intent : undefined;
      return {
        group,
        count,
        countLabel: group.countLabel ?? `${count} ${count === 1 ? 'item' : 'items'}`,
        countIntent: intent ?? 'neutral',
        intent,
        intentClass: tableGroupIntentClass(intent),
        labelColor: tableGroupLabelColor(intent),
        collapsed: collapsedGroupIds.has(group.id),
        selection: selectable
          ? deriveTableSelectionState(group.rows, input.selectedRowIds)
          : null,
      };
    }),
    totalColumns: input.columns.length + (selectable ? 1 : 0),
    allGroupsCollapsed,
    showCollapseAll,
    collapseAllHost: showCollapseAll ? tableCollapseAllHost(input.columns) : undefined,
    flexibleColumnId: tableFlexibleColumnId(input.columns),
    tableStyle: explicitMinWidth == null
      ? undefined
      : { '--ds-table-explicit-min-inline-size': explicitMinWidth },
  };
}

import type { TagContrast, TagIntent } from '../Tag/Tag';
import type { IconColor } from '../Icon/Icon';

export type TableSortDirection = 'asc' | 'desc';
export type TableSelectionMode = 'none' | 'multiple';
export type TableCellAlign = 'start' | 'center' | 'end';
export type TableColumnSticky = 'start' | 'end';
export type TableCaptionVisibility = 'visible' | 'hidden';
export type TableLoadMoreMode = 'auto' | 'manual';
export type TableLoadMoreReason = 'auto' | 'manual' | 'retry';
export type TableColumnWidth = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
/** Semantic color for a group section header (faint surface + bold title). */
export type TableGroupIntent =
  | 'brand'
  | 'neutral'
  | 'negative'
  | 'warning'
  | 'caution'
  | 'positive';

/** Independently sortable label within a compound column header. */
export interface TableHeaderSegment {
  label: string;
  /** Stable key emitted through TableSortState.columnId. */
  sortKey: string;
  /** Visible separator rendered after this label when another segment follows. */
  separator?: string;
}

/** Controlled member-row sort state. Group order is controlled separately. */
export interface TableSortState {
  columnId: string;
  direction: TableSortDirection;
}

/** One controlled grouping level plus the supplied group-order direction. */
export interface TableGroupingState {
  columnId: string;
  direction: TableSortDirection;
}

/** Standard two-line cell content owned by the table renderer. */
export interface TableCellText {
  primary: string | number;
  secondary?: string;
  /** Allow this cell to wrap even when its column truncates by default. */
  wrap?: boolean;
  fontFeature?: 'normal' | 'tabular-nums';
}

/** Two-line text content where both tracks use primary body text. */
export interface TableCellPrimaryText {
  kind: 'primary-text';
  primary: string | number;
  secondary: string | number;
  /** Allow this cell to wrap even when its column truncates by default. */
  wrap?: boolean;
  fontFeature?: 'normal' | 'tabular-nums';
}

/** Applicable data point whose value is currently unavailable. */
export interface TableCellEmpty {
  kind: 'empty';
}

/** Data point that is intentionally not applicable to this row. */
export interface TableCellBlank {
  kind: 'blank';
}

/** Declarative icon-only content rendered by the table's standard cell primitive. */
export interface TableCellIcon {
  kind: 'icon';
  /** Exact canonical IcoMo export name. */
  icon: string;
  color?: IconColor;
  /** Accessible label for informative icons. Omit only when the icon is decorative. */
  label?: string;
  /** Application-owned value used when this icon column participates in sorting. */
  sortValue?: string | number | boolean;
}

/** Declarative 16:9 image preview rendered by the table's standard cell primitive. */
export interface TableCellImage {
  kind: 'image';
  /** Optional image source. Omit it to render the standard bordered placeholder. */
  src?: string;
  /** Accessible description for either the image or its placeholder. */
  alt: string;
}

interface TableCellActionBase {
  kind: 'action';
  /** Stable application-owned action identity emitted with dsCellAction. */
  actionId: string;
  /** Add the ButtonUnfilled resting border. Action cells are unbordered by default. */
  hasBorder?: boolean;
  isInactive?: boolean;
  isLoading?: boolean;
}

/** Declarative ButtonUnfilled content rendered by the table's standard action cell. */
export type TableCellAction = TableCellActionBase & (
  | {
      variant?: 'label';
      label: string;
      icon?: never;
      ariaLabel?: string;
    }
  | {
      variant: 'icon-label';
      label: string;
      icon: string;
      ariaLabel?: string;
    }
  | {
      variant: 'icon';
      label?: never;
      icon: string;
      ariaLabel: string;
    }
);

/** Declarative Tag content rendered by the table's standard cell primitive. */
export type TableCellTagVariant = 'tag-only' | 'tag-with-text' | 'text-with-tag';

interface TableCellTagBase {
  kind: 'tag';
  label: string;
  intent?: TagIntent;
  contrast?: TagContrast;
  icon?: string;
  rounded?: boolean;
}

export type TableCellTag = TableCellTagBase & (
  | {
      variant?: 'tag-only';
      text?: never;
    }
  | {
      variant: Exclude<TableCellTagVariant, 'tag-only'>;
      text: string;
    }
);

export type TableCellValue =
  | string
  | number
  | null
  | undefined
  | TableCellText
  | TableCellPrimaryText
  | TableCellTag
  | TableCellIcon
  | TableCellImage
  | TableCellAction
  | TableCellEmpty
  | TableCellBlank;

export interface TableColumn {
  /** Stable column identity. */
  id: string;
  /** Visible column label. May be empty when headerLabel supplies a non-visual name. */
  header: string;
  /** Screen-reader-only column name for an intentionally blank visual header. */
  headerLabel?: string;
  /** Optional labels for columns that present and sort multiple related data points. */
  headerSegments?: TableHeaderSegment[];
  align?: TableCellAlign;
  sortable?: boolean;
  /** Preferred TokoMo table-column width. Numbers remain available for exceptional custom pixel widths. */
  size?: TableColumnWidth | number;
  /** Minimum accepted preferred width in CSS pixels. */
  minSize?: number;
  /** Maximum accepted preferred width in CSS pixels. */
  maxSize?: number;
  /** Wrap cell text instead of truncating it to one line. */
  wrap?: boolean;
  /** Pin one application column to either inline edge during horizontal scrolling. */
  sticky?: TableColumnSticky;
  /**
   * Declare a trailing application-action lane. Action columns keep fixed
   * geometry and may host grouped table-level controls in their header.
   */
  kind?: 'data' | 'action';
}

export interface TableRow {
  /** Stable identity, unique across all groups. */
  id: string;
  cells: Record<string, TableCellValue>;
  /** Accessible row name used by its selection control. Falls back to the first cell. */
  selectionLabel?: string;
  /** Exclude this row from selection without muting its content. */
  selectable?: boolean;
  /** Keep the row visible while disabling its selection control and styling it as inactive. */
  disabled?: boolean;
  /** Make the complete row a keyboard- and pointer-activatable application target. */
  interactive?: boolean;
}

export interface TableGroup {
  /** Stable group identity. */
  id: string;
  label: string;
  value?: string | number;
  /** Total server-side member count; may exceed the currently loaded row count. */
  totalCount?: number;
  /** Optional localized accessible count phrase such as “18 vehicles”; the visible tag remains numeric. */
  countLabel?: string;
  /**
   * Optional semantic intent for the group section header. Applies a faint
   * intent background and bold intent title color.
   */
  intent?: TableGroupIntent;
  rows: TableRow[];
}

export interface TableSortChangeDetail {
  sort: TableSortState | null;
}

export interface TableGroupingChangeDetail {
  grouping: TableGroupingState;
}

export interface TableSelectionChangeDetail {
  selectedRowIds: string[];
  scope: 'row' | 'all-loaded' | 'group';
  changedRowId?: string;
  /** Present when scope is `group`. */
  groupId?: string;
  selected?: boolean;
}

export interface TableLoadMoreDetail {
  reason: TableLoadMoreReason;
  loadIdentity: string | number;
  loadedRowCount: number;
}

export interface TableCellActionDetail {
  actionId: string;
  rowId: string;
  columnId: string;
}

export interface TableGroupCollapseChangeDetail {
  scope: 'group' | 'all';
  /** Present when a single group was toggled. */
  groupId?: string;
  collapsed: boolean;
  collapsedGroupIds: string[];
}

export interface TableRowActivateDetail {
  rowId: string;
}
